#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.18.0  -  Hit songs (Apple iTunes previews) mixed into clips on the phone
#   * Create > Music > Hit songs: Apple's most played songs (trending) and search, with the
#     30 second preview, cover and artist. The phone asks Apple directly (no server of ours).
#   * A clip (video, recorded in the app or picked from the gallery) with a hit song gets the
#     song mixed in ON THE PHONE when you share: the video's own sound is replaced and the clip
#     is cut to the length of the song preview (30 s). Nothing is re-encoded.
#   * Posts / photo clips / moments with a hit song play the preview next to the media.
#   * New local plugin packages/audio_merge (Android MediaMuxer; no ffmpeg library needed).
#   * tools/merge_audio.sh = the same merge as an ffmpeg command, for checking by hand.
# Run from the project root:   bash update_v1180_hit_songs_merge.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="6424fae96e910bce7787c6dd025b454d9dd2e07abcd913280e6f6b4377936cc3"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/services/online_music_service.dart ] || { echo "ERROR: v1.17.1 is not installed. Run update_v1171_free_music.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh 2>/dev/null || true
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

echo "==> Adding the local plugin to pubspec.yaml..."
python3 - pubspec.yaml <<'PYX'
import re, sys
p = sys.argv[1]
s = open(p).read()
if re.search(r"^[ \t]+audio_merge:", s, re.M):
    print("    pubspec.yaml: audio_merge already there")
else:
    m = re.search(r"^dependencies:[ \t]*\r?\n", s, re.M)
    if not m:
        sys.exit("ERROR: no dependencies: section in pubspec.yaml")
    s = s[:m.end()] + "  audio_merge:\n    path: packages/audio_merge\n" + s[m.end():]
    open(p, "w").write(s)
    print("    pubspec.yaml: added audio_merge (local plugin)")
PYX

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.18.0 is in place."
echo ""
echo "Good to know:"
echo "  * Nothing to set up: no key, no Vercel setting. The app asks Apple directly."
echo "  * The Android build (GitHub Actions) compiles the new local plugin; watch the first run."
echo "  * Check the merge by hand on a computer:  bash tools/merge_audio.sh video.mp4 song.m4a out.mp4"
exit 0
